import fs from'node:fs';import vm from'node:vm';import{canonicalInstrumentDefinition}from'../../src/data/lib/instrument-spell-profiles.js';import{canonicalTravelGoatDefinition}from'../../src/data/lib/travel-goat-profile.js';import{canonicalRodAbsorptionDefinition}from'../../src/data/lib/rod-absorption-source.js';import{canonicalTimedDefenseDefinition}from'../../src/data/lib/timed-defenses-source.js';
const read=p=>fs.readFileSync(new URL('../../src/app/'+p,import.meta.url),'utf8');
export function installInstrumentApp17(engine){let saves=0;const c={S:engine.c.S,FROZEN:false,env:engine.c.genv,structuredClone,canonicalInstrumentDefinition,canonicalTravelGoatDefinition,canonicalRodAbsorptionDefinition,canonicalTimedDefenseDefinition,__set_C:engine.setC,save(){saves++},saveC(){saves++},renderAll(){},renderNotes(){},toast(){},lsGet:()=>null,CKEY:'fixture',D:{hpmax:0},num:(v,d=0)=>Number.isFinite(+v)?+v:d};Object.defineProperty(c,'C',{get:()=>engine.C});vm.createContext(c);const app=read('17-logic-tab-sync-and-test-hooks.js');vm.runInContext(app.slice(app.indexOf('function storedInventoryProjection('),app.indexOf('env.__sheetApply=')),c);const storage=read('04-logic-storage.js');vm.runInContext(storage.split('\n').find(l=>l.startsWith('export var APP_VER=')).replace('export ',''),c);vm.runInContext(storage.split('\n').find(l=>l.startsWith('export function newerApp(')).replace('export ',''),c);vm.runInContext(app.split('\n').find(l=>l.startsWith('function keepNewer(')),c);vm.runInContext(app.slice(app.indexOf('env.__sheetApply='),app.indexOf('env.__sheetName=')),c);vm.runInContext(app.split('\n').find(l=>l.startsWith('env.__sheetSoft=')),c);for(const name of ['instrumentSpells','rodAbsorption','travelGoat'])vm.runInContext(app.split('\n').find(l=>l.startsWith('env.__'+name+'Save=')),c);return {c,get saves(){return saves},soft(next){const before=engine.C;c.env.__sheetSoft(next);return engine.C!==before||engine.C===next},apply(next){const before=engine.C;c.env.__sheetApply(next,false);return engine.C!==before||engine.C===next}};}
